import { backendClient } from './client'

export type AssistantResponse = {
  messageId: string
  content: string
  actionMode: 'suggest' | 'prepare' | 'execute'
  actions?: AssistantAction[]
}

export type AssistantAction = {
  id: string
  label: string
  type: string
  payload: Record<string, unknown>
  requiresConfirmation: boolean
}

export const assistantService = {
  async prompt(input: {
    message: string
    context: Record<string, unknown>
    mode?: 'suggest' | 'prepare' | 'execute'
  }): Promise<AssistantResponse> {
    return backendClient.fetch<AssistantResponse>('/assistant/prompt', {
      method: 'POST',
      body: JSON.stringify(input),
    })
  },

  async executeAction(actionId: string, payload: Record<string, unknown>): Promise<{ success: boolean }> {
    return backendClient.fetch<{ success: boolean }>('/assistant/execute', {
      method: 'POST',
      body: JSON.stringify({ actionId, payload }),
    })
  },
}
